  var P = g.__thornswoodProgression;
  var T = g.__thornswoodTomes;
  if (!P || !T || !T.record) { console.log('[college] the rules or the tomes block is missing, nothing registered'); return; }
  var L = P.TABLE.limits;
  var R = T.record;

