    'Healing': { self: true },
    'Fast Healing': { self: true },
    'Close Wounds': { self: true },
    'Grand Healing': { self: true },
    'Guardian Circle': { self: true },
    'Healing Hands': { self: false },
    'Heal Other': { self: false }
